757→<!-- Redirect links and searches when in dual view mode -->
758→<script>
759→document.addEventListener("DOMContentLoaded", function () {
760→  if (!window.location.pathname.startsWith("/dual")) return;
761→
762→  function getTargetPanel() {
763→    const selected = document.querySelector('input[name="targetPanel"]:checked');
764→    return selected ? selected.value : "left";
765→  }
766→
767→  function loadInPanel(panel, path) {
768→    if (!path) return;
769→    const iframe = document.getElementById(`iframe-${panel}`);
770→    if (!iframe) return;
771→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
772→    iframe.src = url;
773→    const inputBox = document.querySelector(`#panel-${panel} input`);
774→    if (inputBox) inputBox.value = path;
775→    console.log(`Loaded "${url}" into panel "${panel}"`);
776→  }
777→  
778→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
779→    link.addEventListener("click", function (e) {
780→      e.preventDefault();
781→      const path = this.getAttribute("href");
782→      loadInPanel(getTargetPanel(), path);
783→    });
784→  });
785→
786→  const idForm = document.getElementById("idsearchForm");
