792→
793→      let path = null;
794→
795→      if (/^\d+$/.test(input)) {
796→        path = "/go_to/" + encodeURIComponent(input);
797→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
798→        const parts = input.split(/\s+/).filter(Boolean);
799→        path = "/range/" + parts.map(encodeURIComponent).join("/");
800→      } else {
801→        alert("Invalid input format.");
802→        return;
803→      }
804→
805→      loadInPanel(getTargetPanel(), path);
806→    });
807→  }
808→
809→  const searchForm = document.getElementById("searchForm");
