811→    searchForm.addEventListener("submit", function (e) {
812→      e.preventDefault();
813→      const input = searchForm.querySelector(".searchTerm").value.trim();
814→      if (!input) return;
815→
816→      const path = "/search/" + encodeURIComponent(input);
817→      loadInPanel(getTargetPanel(), path);
818→    });
819→  }
820→});
